    					for(var i = 0; i < udc_obj.fileArr.length; i++){
		                    var files = udc_obj.fileArr[i];
		                    for (var j = 0; j < files.length; j++) {
		                        for( var k = 0; k < dltObj.getRowCount(); k++){
		                            var xml = dltObj.getRowXML(k);
		                            var name = WebSquare.xml.getValue(xml,"map/name");

		                            if( name == files[j].name ){
		                                var c_chkVal = dltObj.getCellData(k, "chk");
		                                if(c_chkVal == 1){
		                                	gridView1.setUserData("curIdx", k);
		                                	udc_obj.upload(files[j]);
		                                }

		                            }
		                            else {
		                                // 파일 삭제.
		                            }
		                        } 
		                    }
		                }

		              	window.fileArr = [];


		                var dlt_id = udc_obj.id + "_dataList1";
    					var dltObj = WebSquare.wUnit.getObjById(dlt_id);

    					var _dragGrp = WebSquare.wUnit.getObjById(udc_obj.id + "_dragGrp");

		                var chkArr = gridView1.getCheckedIndex( "chk" );

		                dltObj.removeRows( chkArr );
		                if( dltObj.getRowCount() == 0){
		                    _dragGrp.show();
		                    udc_obj.upload_result_cnt = false;
		                    udc_obj.statusIdx = 0;
		                }

