xf:group.script:

				/**
				* //property handling
				* $w.log("id:" + options.id);
				* $w.log("style:" + options.style);
				* $w.log("class:" + options.class);
				* $w.log("diabled:" + options.diabled);
				*
				* //event trigger
				*/
				var dlt_id = udc_obj.org_id + "_dataList1";
				//var dlt_id = udc_obj.id + "_dataList1";
				var option = {"id" :dlt_id ,
                            "type" : "dataList" ,
                           "option":{ "baseNode": "list", "repeatNode": "map"},
                       "columnInfo":[{"id":"chk", "name":"확인", "dataType":"text", "ignoreStatus":"true"},
                                     {"id":"name", "name":"파일", "dataType":"text"},
                                     {"id":"status", "name":"업로드상태", "dataType":"text"},
                                     {"id":"size", "name":"용량", "dataType":"text"},
                                     {"id":"type", "name":"타입", "dataType":"text"},
                                     {"id":"download", "name":"다운로드", "dataType":"text"}
                                    ]
                 };

    			$p.data.create(option);

				udc_obj.upload_result_cnt;
				udc_obj.statusIdx = 0;
				udc_obj.dropStatus = WebSquare.wUnit.getDomById($p.id+"dropStatus");
	            udc_obj.dropfile = WebSquare.wUnit.getDomById($p.id+"dropfile");
	            udc_obj.fileArr = [];
	            udc_obj.statusArr = [];


	            var dltObj = WebSquare.util.getComponentById( dlt_id );

	            this.dropUpload = function(e) {
				    WebSquare.event.preventDefault(e);
				    var files = e.dataTransfer.files;

				    udc_obj.fileArr.push(files);
				    if( !udc_obj.upload_result_cnt ){
				    	dragGrp.hide();
				    }
				    var upComplete = gridView1.getUserData("complete");
				    if( upComplete == true){
				    	dltObj.setJSON(files,false);
				    	gridView1.setUserData("complete", false);
				    	udc_obj.statusIdx = 0;
				    }else{
				    	dltObj.setJSON(files,true);
				    }
				    udc_obj.upload_result_cnt = true;
				};

				this.upload = function(file){
					var formData = new FormData();
				    formData.append("file", file);
				    var xhr = new XMLHttpRequest();
				    xhr.upload.addEventListener("progress", udc_obj.uploadProgress, false);
				    xhr.addEventListener("load", udc_obj.uploadComplete, false);
				    xhr.open("POST", "/websquare5/dragdrop.jsp", true); // If async=false, then you'll miss progress bar support.
				    xhr.send(formData);
				};

				this.uploadProgress = function(e) {
				    // Note: doesn't work with async=false.
					var progress = Math.round(e.loaded / e.total * 100);
				    //dropStatus.innerHTML = "Progress " + progress + "%";
				    var progressStr = "" + progress + "%";
				    dltObj.setCellData(udc_obj.statusIdx, "status", progressStr);
				};

				this.uploadComplete = function(e) {
					dltObj.setCellData(udc_obj.statusIdx, "status", "100%");
					udc_obj.statusIdx++;
					if (statusIdx == dltObj.getRowCount()){
						gridView1.setUserData("complete", true);
						gridView1.setColumnDisabled("download", false);
					}
					if (udc_obj.upload_result_cnt) {
						//dropStatus.innerHTML = e.target.responseText;
						udc_obj.upload_result_cnt = false;
					} else {
					   // dropStatus.innerHTML = dropStatus.innerHTML+"\n"+e.target.responseText;
					   // dropfile.innerHTML = "";
					}
				};

				WebSquare.event.addListener( dropbox.render , "ondragenter" , function(e){WebSquare.event.stopEvent(e);}, false);
            	WebSquare.event.addListener( dropbox.render , "ondragend" , function(e){WebSquare.event.stopEvent(e);}, false);
            	WebSquare.event.addListener( dropbox.render , "ondragover" , function(e){WebSquare.event.stopEvent(e);}, false);
            	WebSquare.event.addListener( dropbox.render, "ondrop" , udc_obj.dropUpload, false);

            	/*
            	 * 그 외 사용자 정의 함수 
            	 */ 

            	// 데이터리스트를 반환한다. 
            	this.getDataList = function(){
            		return WebSquare.wUnit.getObjById( dlt_id );
            	};
